390	class WorksThumbnailRuntime {
391	  async warm(
392	    meshes: ReadonlyArray<THREE.Mesh>,
393	    placeholderImage: string,
394	    cardSize: WorkCardSize,
395	    log: (step: string, payload?: Record<string, unknown>) => void,
396	    onImageLoaded?: (mesh: THREE.Mesh, image: HTMLImageElement) => void,
397	  ): Promise<void> {
398	    let fallback: HTMLImageElement | null = null;
399	    const ensureFallback = async (): Promise<HTMLImageElement> => {
400	      if (!fallback) {
401	        fallback = await WorkCard.loadPlaceholderImage(placeholderImage);
402	      }
403	      return fallback;
404	    };
405	
406	    let index = 0;
407	    const batchSize = 4;
408	    const runBatch = async (): Promise<void> => {
409	      const end = Math.min(index + batchSize, meshes.length);
410	      const slice = meshes.slice(index, end);
411	      await Promise.all(
412	        slice.map(async (mesh) => {
413	          if (!mesh) return;
414	          const userData = mesh.userData as WorkCardUserData;
415	          const material = mesh.material as THREE.MeshBasicMaterial;
416	          const map = material.map;
417	          if (!map || !(map instanceof THREE.CanvasTexture)) return;
418	          const thumb = userData.proj.thumbnailImage?.trim() ?? "";
419	          let img: HTMLImageElement;
420	          if (thumb) {
421	            try {
422	              img = await WorkCard.loadImage(thumb);
423	            } catch {
424	              img = await ensureFallback();
425	            }
426	          } else {
427	            img = await ensureFallback();
428	          }
429	          WorkCard.updateTextureImage(
430	            map,
431	            userData.proj,
432	            cardSize,
433	            img,
434	            SCATTER_CARD_RENDER_OPTIONS,
435	          );
436	          onImageLoaded?.(mesh, img);
437	        }),
438	      );
439	      index = end;
440	      log("warmThumbnails.batch", { updatedUntil: index, total: meshes.length });
441	      if (index < meshes.length) {
442	        FrameScheduler.request(() => {
443	          void runBatch();
444	        });
445	      }
446	    };
447	    void runBatch();
448	  }
449	}
