564	  applyCategory(category: string | null): void {
565	    if (this.activeCategory !== category) {
566	      this._filterPrevCategory = this.activeCategory;
567	      this._filterBlendStartMs = performance.now();
568	    }
569	    this.activeCategory = category;
570	    const scatterPositions =
571	      category === null ? this.scatterPositions : this.categoryScatterPositions;
572	    const nextPositions = [...this.scatterPositions];
573	    const nextInteractiveMeshes: THREE.Mesh[] = [];
574	    const visiblePositions: WorksScatterPosition[] = [];
575	    let visibleIndex = 0;
576	    for (let index = 0; index < this.meshes.length; index += 1) {
