588	    this.cameraMotionRuntime.setTargetZ(this.cameraMotionRuntime.readBaseCamZ());
589	    this.cameraMotionRuntime.setDynamicClamp(visiblePositions);
590	    if (this.hovered && !this.isMeshInCategory(this.hovered)) this.hovered = null;
