723	  private start(): void {
724	    this.canvas = this.root.querySelector<HTMLCanvasElement>(`#${this.canvasId}`);
725	    if (!this.canvas) return;
726	
727	    this.scene = new THREE.Scene();
728	    const viewport = this.viewportRuntime.read();
729	    const halfHeight =
730	      Math.tan((this.config.camFov * Math.PI) / 360) * this.config.camZ;
731	    const halfWidth = halfHeight * (viewport.width / viewport.height);
732	    this.camera = new THREE.OrthographicCamera(
733	      -halfWidth,
734	      halfWidth,
735	      halfHeight,
736	      -halfHeight,
737	      this.config.camNear,
738	      this.config.camFar,
739	    );
740	    const introCamera = this.introEntryState?.camera;
741	    this.camera.position.set(
742	      introCamera?.position?.x ?? 0,
743	      introCamera?.position?.y ?? 0,
744	      introCamera?.position?.z ?? this.config.camZ,
745	    );
746	    this.camera.lookAt(this.camera.position.x, this.camera.position.y, 0);
747	    this.cameraMotionRuntime.primeFromCameraPosition(
748	      this.camera.position.x,
749	      this.camera.position.y,
750	      this.camera.position.z,
751	    );
752	    this.cameraMotionRuntime.activateScatter();
753	
754	    this.renderer = new THREE.WebGLRenderer({
755	      canvas: this.canvas,
756	      antialias: this.rendererConfig.antialias,
757	      alpha: this.rendererConfig.alpha,
758	      powerPreference: this.rendererConfig.powerPreference,
759	    });
760	    this.renderer.setSize(viewport.width, viewport.height);
761	    this.renderer.setPixelRatio(viewport.dpr);
762	    this.renderer.setClearColor(0x000000, 0);
763	    this.renderer.shadowMap.enabled = false;
764	
765	    const scene = this.scene;
766	    if (!scene) return;
767	    const cardResources = this.meshRuntime.create(
768	      scene,
769	      this.projects,
770	      this.scatterPositions,
771	      this.config,
772	    );
773	    this.meshes = cardResources.meshes;
774	    this._cardSize = cardResources.cardSize;
775	    this._cardScale = Math.min(1, viewport.width / CARD_SCALE_BASE_WIDTH);
776	    this._rebuildScatterPositions();
777	
778	    this.bindEvents();
779	    this.applyCategory(this.activeCategory);
780	    this.startLoop();
781	    void this.thumbnailRuntime
782	      .warm(
783	        this.meshes,
784	        this.placeholderImage,
785	        cardResources.cardSize,
786	        () => undefined,
787	        (mesh, img) => {
788	          const userData = mesh.userData as WorkCardUserData;
789	          userData.loadedImage = img;
790	        },
791	      )
792	      .catch(() => undefined);
