795	  private bindEvents(): void {
796	    const canvas = this.canvas;
797	    if (!canvas) return;
798	
799	    const onPointerMove = (event: PointerEvent): void => {
800	      const viewport = this.viewportRuntime.read();
801	      if (this.viewMode !== "scatter") {
802	        this.hovered = null;
803	        return;
804	      }
805	      if (!this.camera) return;
806	      if (this.activePointerId !== event.pointerId) {
807	        if (this.activePointerId === null) {
808	          this.hovered = this.hitRuntime.resolve(
809	            this.camera,
810	            viewport,
811	            { x: event.clientX, y: event.clientY },
812	            this.interactiveMeshes,
813	          );
814	        }
815	        return;
816	      }
817	      if (this.cameraMotionRuntime.isDragging) {
818	        if (
819	          !this.dragInteractionStarted &&
820	          Math.hypot(event.clientX - this.mouseDownX, event.clientY - this.mouseDownY) >=
821	            WorksSceneManager._dragStartThresholdPx
822	        ) {
823	          this.dragInteractionStarted = true;
824	          this.onInteractionStart?.();
825	        }
826	        this.cameraMotionRuntime.updateDrag(
827	          viewport,
828	          this.viewportRuntime.readHalfView(this.camera),
829	          { x: event.clientX, y: event.clientY },
830	          this._isTouchPointer ? 2.0 : 1.0,
831	        );
832	        this.hovered = null;
833	        return;
834	      }
835	      this.hovered = this.hitRuntime.resolve(
836	        this.camera,
837	        viewport,
838	        { x: event.clientX, y: event.clientY },
839	        this.interactiveMeshes,
840	      );
841	    };
842	    const onPointerDown = (event: PointerEvent): void => {
843	      if (this.viewMode !== "scatter" || !this.camera) return;
844	      if (event.button !== 0) return;
845	      this.mouseDownX = event.clientX;
846	      this.mouseDownY = event.clientY;
847	      this.dragInteractionStarted = false;
848	      this.activePointerId = event.pointerId;
849	      this._isTouchPointer = event.pointerType === "touch";
850	      this.mouseDownMesh = this.hitRuntime.resolve(
851	        this.camera,
852	        this.viewportRuntime.read(),
853	        { x: event.clientX, y: event.clientY },
854	        this.interactiveMeshes,
855	      );
856	      this.cameraMotionRuntime.beginDrag(this.camera, {
857	        x: event.clientX,
858	        y: event.clientY,
859	      });
860	      canvas.setPointerCapture(event.pointerId);
861	    };
862	    const onPointerUp = (event: PointerEvent): void => {
863	      if (this.activePointerId !== event.pointerId) return;
864	      if (
865	        this.viewMode === "scatter" &&
866	        this.mouseDownMesh &&
867	        this.isMeshInCategory(this.mouseDownMesh) &&
868	        Math.hypot(event.clientX - this.mouseDownX, event.clientY - this.mouseDownY) <
869	          WorksSceneManager._dragStartThresholdPx
870	      ) {
871	        const userData = this.mouseDownMesh.userData as WorkCardUserData;
872	        this.onSelect?.(userData.detailPath);
873	      }
874	      this._resetPointerInteraction(event.pointerId);
875	    };
876	    const onPointerCancel = (event: PointerEvent): void => {
877	      if (this.activePointerId !== event.pointerId) return;
878	      this._resetPointerInteraction(event.pointerId);
879	    };
880	    const onPointerLeave = (): void => {
881	      if (this.activePointerId !== null) return;
882	      this.hovered = null;
883	    };
884	    const onResize = (): void => {
885	      if (!this.camera || !this.renderer) return;
886	      const viewport = this.viewportRuntime.read();
887	      if (this.camera instanceof THREE.OrthographicCamera) {
888	        const halfHeight =
889	          Math.tan((this.config.camFov * Math.PI) / 360) * this.config.camZ;
890	        const halfWidth = halfHeight * (viewport.width / viewport.height);
891	        this.camera.left = -halfWidth;
892	        this.camera.right = halfWidth;
893	        this.camera.top = halfHeight;
894	        this.camera.bottom = -halfHeight;
895	        this.camera.updateProjectionMatrix();
896	      }
897	      this.renderer.setPixelRatio(viewport.dpr);
898	      this.renderer.setSize(viewport.width, viewport.height);
899	      this._cardScale = Math.min(1, viewport.width / CARD_SCALE_BASE_WIDTH);
900	      this._rebuildScatterPositions();
901	      this.applyCategory(this.activeCategory);
902	    };
903	    canvas.addEventListener("pointermove", onPointerMove);
904	    canvas.addEventListener("pointerdown", onPointerDown);
905	    canvas.addEventListener("pointerup", onPointerUp);
906	    canvas.addEventListener("pointercancel", onPointerCancel);
907	    canvas.addEventListener("pointerleave", onPointerLeave);
908	    window.addEventListener("resize", onResize);
909	    this.cleanup.push(
910	      () => canvas.removeEventListener("pointermove", onPointerMove),
911	      () => canvas.removeEventListener("pointerdown", onPointerDown),
912	      () => canvas.removeEventListener("pointerup", onPointerUp),
913	      () => canvas.removeEventListener("pointercancel", onPointerCancel),
914	      () => canvas.removeEventListener("pointerleave", onPointerLeave),
915	      () => window.removeEventListener("resize", onResize),
916	    );
917	  }
